for(let id of ['ac-start-range','ac-end-range'])$(id).oninput=()=>{let a=Number($('ac-start-range').value),b=Number($('ac-end-range').value);if(id==='ac-start-range')a=Math.min(a,b-.05);else b=Math.max(b,a+.05);$('ac-start').value=time(Math.max(0,a));$('ac-end').value=time(Math.min(buffer.duration,b));edited()};
$('ac-all').onclick=()=>{$('ac-start').value='0:00.00';$('ac-end').value=time(buffer.duration);edited()};$('ac-format').onchange=invalidate;$('ac-fade').onchange=invalidate;
function channels(a,b){let first=Math.round(a*buffer.sampleRate),last=Math.min(buffer.length,Math.round(b*buffer.sampleRate)),n=last-first,result=[];for(let ch=0;ch<buffer.numberOfChannels;ch++){let x=buffer.getChannelData(ch).slice(first,last);if($('ac-fade').checked){let fade=Math.min(Math.round(buffer.sampleRate*.5),Math.floor(n/2));for(let i=0;i<fade;i++){let gain=i/fade;x[i]*=gain;x[n-1-i]*=gain}}result.push(x)}return result}
