function wav(data,rate){let n=data[0].length,ch=data.length,b=new ArrayBuffer(44+n*ch*2),v=new DataView(b),text=(p,s)=>{for(let i=0;i<s.length;i++)v.setUint8(p+i,s.charCodeAt(i))};text(0,'RIFF');v.setUint32(4,b.byteLength-8,true);text(8,'WAVEfmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,ch,true);v.setUint32(24,rate,true);v.setUint32(28,rate*ch*2,true);v.setUint16(32,ch*2,true);v.setUint16(34,16,true);text(36,'data');v.setUint32(40,n*ch*2,true);let p=44;for(let i=0;i<n;i++)for(let c=0;c<ch;c++){let x=Math.max(-1,Math.min(1,data[c][i]));v.setInt16(p,Math.round(x*(x<0?32768:32767)),true);p+=2}return new Blob([b],{type:'audio/wav'})}
function ready(blob,ext,id){clearTimeout(timer);if(id!==seq)return;url=URL.createObjectURL(blob);let a=document.createElement('a');a.href=url;a.download='audio-clip.'+ext;a.className='ac-download';a.textContent='حمّل المقطع '+ext.toUpperCase();let preview=document.createElement('audio');preview.controls=true;preview.src=url;$('ac-output').replaceChildren(a,preview);$('ac-output').hidden=false;busy=false;lock();say('المقطع جاهز: '+(blob.size/1024).toFixed(1)+' KB.')}
$('ac-save').onclick=()=>{try{let[a,b]=bounds();invalidate();let id=++seq,data=channels(a,b),ext=$('ac-format').value;busy=true;lock();say('جاري تجهيز المقطع...',true);if(ext==='wav'){ready(wav(data,buffer.sampleRate),ext,id);return}worker=new Worker('/audio-encode-worker.js');timer=setTimeout(()=>{if(id!==seq||!worker)return;worker.terminate();worker=null;busy=false;lock();say('تجهيز MP3 أخد وقت طويل. جرّب مقطع أقصر أو WAV.');},120000);worker.onmessage=e=>{if(id!==seq)return;if(e.data.error){clearTimeout(timer);busy=false;lock();say('تعذر تحميل محرك MP3. جرّب WAV أو تأكد من الاتصال.');worker.terminate();worker=null;return}if(e.data.blob){ready(e.data.blob,'mp3',id);worker.terminate();worker=null}else if(e.data.progress!==undefined)say('تجهيز MP3: '+Math.floor(e.data.progress*100)+'%',true)};worker.onerror=()=>{if(id!==seq)return;clearTimeout(timer);busy=false;lock();say('تعذر تجهيز MP3. جرّب WAV.');worker.terminate();worker=null};worker.postMessage({channels:data,rate:buffer.sampleRate},data.map(a=>a.buffer))}catch(e){busy=false;lock();say(e.message)}};
