function stop(){seq++;clearTimeout(timer);if(worker)worker.terminate();worker=null;busy=false;lock()}
function lock(){file.disabled=busy;$('va-run').disabled=busy;$('va-mode').disabled=busy;$('va-cancel').hidden=!busy}
function clear(){stop();resultClear();selected=null;meta=null;file.value='';$('va-settings').hidden=true;app.classList.remove('va-loaded');say('اختار الفيديو، وبعدها استخرج صوته أو احفظه صامت.')}
