function launch(mode){stop();let id=seq;busy=true;lock();say(mode==='inspect'?'Loading...':'جاري تجهيز الملف...',true);worker=new Worker('/video-audio-worker.js',{type:'module'});timer=setTimeout(()=>{if(id!==seq)return;stop();say('المعالجة أخدت وقت طويل. جرّب فيديو أصغر.');if(meta)modeHelp()},120000);worker.onerror=()=>{if(id!==seq)return;stop();say('تعذر تشغيل المحرك. راجع الاتصال أو جرّب متصفحًا حديثًا.');if(meta)modeHelp()};worker.onmessage=e=>{if(id!==seq)return;let d=e.data;if(d.progress!==undefined){say('تجهيز الملف: '+Math.floor(d.progress*100)+'%',true);return}stop();if(d.error){const messages={video:'الملف مفيهوش فيديو قابل للقراءة. اختار MP4 أوMOV أوWebM سليم.',duration:'الحد ٣٠ دقيقة، ولازم مدة الفيديو تكون قابلة للقراءة.',silent:'الفيديو مفيهوش مسار صوت.',codec:'ترميز الملف مش مدعوم للعملية دي. جرّب فيديو MP4 بصوت AAC.',invalid:'تعذرت قراءة الملف أو تجهيزه. ممكن يكون تالفًا أو ترميزه غير مدعوم.'};if(meta)modeHelp();say(messages[d.error]||messages.invalid);return}if(d.meta){meta=d.meta;$('va-info').textContent=selected.name+' - '+Math.floor(meta.duration/60)+':'+String(Math.floor(meta.duration%60)).padStart(2,'0');$('va-settings').hidden=false;app.classList.add('va-loaded');$('va-mode').value=meta.hasAudio&&meta.extract?'extract':'mute';modeHelp();say('اختار الوظيفة وبعدها جهّز الملف.');return}if(d.done){url=URL.createObjectURL(d.blob);let a=document.createElement('a');a.href=url;a.className='va-download';a.download=(mode==='extract'?'video-audio.':'video-muted.')+d.ext;a.textContent='حمّل '+d.ext.toUpperCase();let media=document.createElement(mode==='extract'?'audio':'video');media.controls=true;media.preload='metadata';media.src=url;media.onloadedmetadata=()=>{if(mode==='mute'&&meta&&Math.abs(media.duration-meta.duration)>2)say('راجع مدة النسخة الجديدة قبل المشاركة.')};let note=document.createElement('p');note.className='va-help';note.textContent='الملف جاهز: '+(d.blob.size/1048576).toFixed(2)+' ميجا. راجع النتيجة قبل المشاركة.';$('va-result').append(a,note,media);$('va-result').hidden=false;say('الملف جاهز للتحميل.')}};worker.postMessage({file:selected,mode})}
file.onchange=()=>{const f=file.files[0];clear();if(!f)return;if(!/\.(mp4|mov|webm)$/i.test(f.name)){say('اختار فيديو MP4 أوMOV أوWebM.');return}if(f.size>100*1048576||f.size===0){say('اختار ملفًا غير فارغ لا يزيد عن ١٠٠ ميجا.');return}selected=f;launch('inspect')};$('va-mode').onchange=()=>{modeHelp();say('')};$('va-run').onclick=()=>{if(!selected||!meta||busy)return;resultClear();launch($('va-mode').value)};$('va-clear').onclick=clear;$('va-cancel').onclick=()=>{stop();if(meta)modeHelp();say('تم الإلغاء. اختار وظيفة أو ملف تاني.')};const watch=new MutationObserver(()=>{if(!document.contains(file)){stop();resultClear();selected=null;meta=null;watch.disconnect()}});watch.observe(document.getElementById('tool-body'),{childList:true});
