function parse(s){s=s.trim().replace(/[٠-٩]/g,d=>String(d.charCodeAt(0)-1632)).replace('٫','.');if(!s)return NaN;let a=s.split(':');if(a.length>2||a.some(x=>!/^\d+(\.\d+)?$/.test(x)))return NaN;return a.length===2?Number(a[0])*60+Number(a[1]):Number(a[0])}
