function info(){let a=0,b=meta?meta.duration:0;try{[a,b]=bounds()}catch(e){}$('vt-selection').textContent='الفيديو '+time(meta.duration)+' | الجزء المحدد '+time(Math.max(0,b-a))}
function stopPlay(){if(playHandler){preview.removeEventListener('timeupdate',playHandler);playHandler=null}preview.pause()}
function invalidate(){stopPlay();if(url){let old=$('vt-output').querySelector('video');if(old){old.removeAttribute('src');old.load()}URL.revokeObjectURL(url);url=null}$('vt-output').replaceChildren();$('vt-output').hidden=true}
function lock(){file.disabled=busy;for(let id of ['vt-save','vt-play','vt-stop','vt-all','vt-start','vt-end','vt-start-range','vt-end-range'])$(id).disabled=busy;$('vt-cancel').hidden=!busy}
function kill(){seq++;clearTimeout(timer);if(worker)worker.terminate();worker=null;busy=false;lock()}
