function launch(mode,start,end){kill();let id=seq;busy=true;lock();say(mode==='inspect'?'Loading...':'جاري قص الفيديو...',true);worker=new Worker('/video-trim-worker.js',{type:'module'});let arm=()=>{clearTimeout(timer);timer=setTimeout(()=>{if(id!==seq)return;kill();say('المعالجة أخدت وقت طويل. جرّب جزءًا أقصر أو فيديو أصغر.')},120000)};arm();worker.onerror=()=>{if(id!==seq)return;kill();say('تعذر تشغيل المحرك. راجع الاتصال أو جرّب متصفحًا حديثًا.')};worker.onmessage=e=>{if(id!==seq)return;let d=e.data;arm();if(d.progress!==undefined){say('قص الفيديو: '+Math.floor(d.progress*100)+'%',true);return}kill();if(d.error){const messages={video:'الملف مفيهوش فيديو قابل للقراءة. اختار MP4 أوMOV أوWebM أوMKV سليم.',duration:'الحد ٣٠ دقيقة، ولازم مدة الفيديو تكون قابلة للقراءة.',codec:'ترميز الفيديو ده مش مدعوم للقص هنا. جرّب فيديو MP4 عادي.',audio:'متصفحك مش قادر يحفظ الصوت داخل MP4 هنا. جرّب متصفحًا حديثًا.',empty:'النتيجة طلعت فاضية. جرّب جزءًا مختلفًا.',invalid:'تعذرت قراءة الملف أو قصّه. ممكن يكون تالفًا أو ترميزه غير مدعوم.'};say(messages[d.error]||messages.invalid);return}if(d.meta){meta=d.meta;if(!meta.decodable){say('ترميز الفيديو ده مش مدعوم على جهازك. جرّب فيديو MP4 عادي.');meta=null;return}if(!meta.encodable){say('متصفحك مش بيدعم تجهيز فيديو MP4 هنا. جرّب متصفحًا حديثًا.');meta=null;return}$('vt-name').textContent=selected.name+' - '+time(meta.duration)+(meta.width?' - '+meta.width+'×'+meta.height:'');$('vt-start').value='0:00.0';$('vt-end').value=time(meta.duration);for(let n of ['vt-start-range','vt-end-range'])$(n).max=meta.duration;$('vt-start-range').value=0;$('vt-end-range').value=meta.duration;$('vt-editor').hidden=false;app.classList.add('vt-loaded');info();say('حدد الجزء وبعدها اضغط قص وحمّل.');return}if(d.done){url=URL.createObjectURL(d.blob);let a=document.createElement('a');a.href=url;a.className='vt-download';a.download='video-trimmed.mp4';a.textContent='حمّل الفيديو MP4';let note=document.createElement('p');note.className='vt-help';note.textContent='الفيديو جاهز: '+(d.blob.size/1048576).toFixed(2)+' ميجا. راجعه قبل المشاركة.';let v=document.createElement('video');v.controls=true;v.playsInline=true;v.preload='metadata';v.src=url;$('vt-output').replaceChildren(a,note,v);$('vt-output').hidden=false;say('الفيديو جاهز للتحميل.')}};worker.postMessage(mode==='inspect'?{file:selected,mode}:{file:selected,mode,start,end})}
file.onchange=()=>{const f=file.files[0];clear();if(!f)return;if(!/\.(mp4|mov|webm|mkv)$/i.test(f.name)){say('اختار فيديو MP4 أوMOV أوWebM أوMKV.');return}if(f.size>100*1048576||f.size===0){say('اختار ملفًا غير فارغ لا يزيد عن ١٠٠ ميجا.');return}selected=f;preview.src=URL.createObjectURL(f);preview.onerror=()=>{playable=false;preview.hidden=true;$('vt-preview-note').hidden=false};launch('inspect')};
for(let id of ['vt-start','vt-end'])$(id).oninput=edited;
for(let id of ['vt-start-range','vt-end-range'])$(id).oninput=()=>{let a=Number($('vt-start-range').value),b=Number($('vt-end-range').value);if(id==='vt-start-range')a=Math.min(a,b-.1);else b=Math.max(b,a+.1);$('vt-start').value=time(Math.max(0,a));$('vt-end').value=time(Math.min(meta.duration,b));seek(Number(id==='vt-start-range'?a:b));edited()};
$('vt-all').onclick=()=>{$('vt-start').value='0:00.0';$('vt-end').value=time(meta.duration);edited()};
$('vt-play').onclick=()=>{try{let[a,b]=bounds();if(!playable){say('المعاينة مش مدعومة للصيغة دي في متصفحك.');return}stopPlay();preview.currentTime=a;playHandler=()=>{if(preview.currentTime>=b){stopPlay();say('')}};preview.addEventListener('timeupdate',playHandler);preview.play().catch(()=>{});say('جاري تشغيل الجزء المحدد.')}catch(e){say(e.message)}};
